// Generated by scripts/symbology/gen_app6d_catalog.py and shared with the
// agent's Python library.

export type CatalogCode = { code: string; name: string; uk: string };
export type CatalogEntity = { code: string; name: string; path: string[] };
export type CatalogSymbolSet = {
  code: string;
  name: string;
  uk: string;
  entities: CatalogEntity[];
  modifier1: Array<{ code: string; name: string }>;
  modifier2: Array<{ code: string; name: string }>;
};
export type CatalogAlias = {
  label: string;
  terms: string[];
  symbolSet: string;
  entity: string;
  modifier1: string;
  modifier2: string;
  hq: string;
  english: string;
};
export type App6dCatalog = {
  identities: CatalogCode[];
  statuses: CatalogCode[];
  hqTfDummy: CatalogCode[];
  echelons: CatalogCode[];
  mobility: CatalogCode[];
  symbolSets: CatalogSymbolSet[];
  aliases: CatalogAlias[];
};

/** A symbol type: everything in a SIDC except identity, status, HQ and echelon. */
export type SymbolType = {
  symbolSet: string;
  entity: string;
  modifier1: string;
  modifier2: string;
  label: string;
  detail: string;
};

export type SidcParts = {
  version: string;
  context: string;
  identity: string;
  symbolSet: string;
  status: string;
  hq: string;
  echelon: string;
  entity: string;
  modifier1: string;
  modifier2: string;
};

const CATALOG_URL = '/data/app6d-catalog.json';
let catalogLoad: Promise<App6dCatalog> | null = null;

export function loadCatalog(): Promise<App6dCatalog> {
  catalogLoad ??= fetch(CATALOG_URL).then((response) => {
    if (!response.ok) throw new Error(`APP-6D catalog: HTTP ${response.status}`);
    return response.json() as Promise<App6dCatalog>;
  });
  catalogLoad.catch(() => {
    catalogLoad = null;
  });
  return catalogLoad;
}

export function sidcParts(sidc: string): SidcParts {
  return {
    version: sidc.slice(0, 2),
    context: sidc.slice(2, 3),
    identity: sidc.slice(3, 4),
    symbolSet: sidc.slice(4, 6),
    status: sidc.slice(6, 7),
    hq: sidc.slice(7, 8),
    echelon: sidc.slice(8, 10),
    entity: sidc.slice(10, 16),
    modifier1: sidc.slice(16, 18),
    modifier2: sidc.slice(18, 20),
  };
}

export function joinSidc(parts: SidcParts): string {
  return [
    parts.version,
    parts.context,
    parts.identity,
    parts.symbolSet,
    parts.status,
    parts.hq,
    parts.echelon,
    parts.entity,
    parts.modifier1,
    parts.modifier2,
  ].join('');
}

function normalize(text: string): string {
  return text.toLowerCase().replace(/[’ʼ]/g, "'").replace(/\s+/g, ' ').trim();
}

function findEntity(catalog: App6dCatalog, symbolSet: string, entity: string) {
  const set = catalog.symbolSets.find((item) => item.code === symbolSet);
  return { set, entity: set?.entities.find((item) => item.code === entity) };
}

/** Ukrainian aliases first, then English catalog paths. */
export function searchSymbolTypes(catalog: App6dCatalog, query: string, limit = 30): SymbolType[] {
  const needle = normalize(query);
  const results: SymbolType[] = [];
  const seen = new Set<string>();
  const push = (item: SymbolType) => {
    const key = `${item.symbolSet}:${item.entity}:${item.modifier1}:${item.modifier2}`;
    if (seen.has(key)) return;
    seen.add(key);
    results.push(item);
  };
  const rank = (alias: CatalogAlias) => {
    const words = [alias.label, ...alias.terms].map(normalize);
    if (words.some((word) => word === needle)) return 0;
    if (words.some((word) => word.startsWith(needle))) return 1;
    return words.join(' ').includes(needle) ? 2 : 3;
  };
  const aliases = needle
    ? catalog.aliases
        .map((alias, index) => ({ alias, index, score: rank(alias) }))
        .filter((item) => item.score < 3)
        .sort((a, b) => a.score - b.score || a.index - b.index)
        .map((item) => item.alias)
    : catalog.aliases;
  for (const alias of aliases) {
    push({
      symbolSet: alias.symbolSet,
      entity: alias.entity,
      modifier1: alias.modifier1,
      modifier2: alias.modifier2,
      label: alias.label,
      detail: alias.english,
    });
  }
  if (needle) {
    for (const set of catalog.symbolSets) {
      for (const entity of set.entities) {
        if (normalize(entity.path.join(' ')).includes(needle)) {
          push({
            symbolSet: set.code,
            entity: entity.code,
            modifier1: '00',
            modifier2: '00',
            label: entity.name,
            detail: `${set.uk} · ${entity.path.join(' / ')}`,
          });
        }
      }
    }
  }
  return results.slice(0, limit);
}

function codeLabel(items: CatalogCode[], code: string): string {
  return items.find((item) => item.code === code)?.uk ?? code;
}

/** "Ворожий · БпЛА" style label for lists and tooltips. */
export function describeSidc(catalog: App6dCatalog | null, sidc: string): string {
  if (!/^\d{20}$/.test(sidc)) return sidc;
  const parts = sidcParts(sidc);
  if (!catalog) return sidc;
  const alias = catalog.aliases.find(
    (item) =>
      item.symbolSet === parts.symbolSet &&
      item.entity === parts.entity &&
      item.modifier1 === parts.modifier1,
  );
  const { set, entity } = findEntity(catalog, parts.symbolSet, parts.entity);
  const type = alias?.label ?? entity?.name ?? set?.uk ?? `${parts.symbolSet}/${parts.entity}`;
  const pieces = [codeLabel(catalog.identities, parts.identity), type];
  if (parts.status !== '0') pieces.push(codeLabel(catalog.statuses, parts.status));
  if (parts.echelon !== '00')
    pieces.push(codeLabel([...catalog.echelons, ...catalog.mobility], parts.echelon));
  return pieces.join(' · ');
}

export function symbolTypeOf(catalog: App6dCatalog | null, sidc: string): SymbolType {
  const parts = sidcParts(sidc);
  const [type] = catalog
    ? searchSymbolTypes(catalog, '', catalog.aliases.length).filter(
        (item) =>
          item.symbolSet === parts.symbolSet &&
          item.entity === parts.entity &&
          item.modifier1 === parts.modifier1,
      )
    : [];
  if (type) return type;
  const { set, entity } = catalog
    ? findEntity(catalog, parts.symbolSet, parts.entity)
    : { set: undefined, entity: undefined };
  return {
    symbolSet: parts.symbolSet,
    entity: parts.entity,
    modifier1: parts.modifier1,
    modifier2: parts.modifier2,
    label: entity?.name ?? `${parts.symbolSet}/${parts.entity}`,
    detail: set ? `${set.uk} · ${entity?.path.join(' / ') ?? ''}` : '',
  };
}
